def record_checks(apps, schema_editor):
    """Packs published before checks could change were published under every check of their kind."""
    PackVersion = apps.get_model("refdata", "PackVersion")
    TieOutRequirement = apps.get_model("refdata", "TieOutRequirement")
    names = {}
    for r in TieOutRequirement.objects.order_by("name"):
        names.setdefault(r.kind, []).append(r.name)
    for pack in PackVersion.objects.exclude(status="draft"):
        pack.checks_at_publication = names.get(pack.kind, [])
        pack.save(update_fields=["checks_at_publication"])


